    arg = NULL, ..., alignmentgroup = NULL, cliponaxis = NULL,
    connectgaps = NULL, customdata = NULL, dx = NULL, dy = NULL,
    error_x = NULL, error_y = NULL, fill = NULL, fillcolor = NULL,
