    hoverinfo = NULL, hoverlabel = NULL, hoveron = NULL,
    hovertemplate = NULL, hovertemplatefallback = NULL, hovertext = NULL,
    ids = NULL, legend = NULL, legendgroup = NULL, legendgrouptitle = NULL,
    legendrank = NULL, legendwidth = NULL, line = NULL, marker = NULL,
    meta = NULL, mode = NULL, name = NULL, offsetgroup = NULL,
    opacity = NULL, orientation = NULL, selected = NULL,
    selectedpoints = NULL, showlegend = NULL, stackgaps = NULL,
    stackgroup = NULL, text = NULL, textfont = NULL, textposition = NULL,
    texttemplate = NULL, texttemplatefallback = NULL, uid = NULL,
    uirevision = NULL, unselected = NULL, visible = NULL, x = NULL,
    x0 = NULL, xaxis = NULL, xcalendar = NULL, xhoverformat = NULL,
    xperiod = NULL, xperiod0 = NULL, xperiodalignment = NULL, y = NULL,
    y0 = NULL, yaxis = NULL, ycalendar = NULL, yhoverformat = NULL,
    yperiod = NULL, yperiod0 = NULL, yperiodalignment = NULL, zorder = NULL,
    skip_invalid = FALSE
) {
  plotly_object("scatter", arg, environment(), list(...), skip_invalid)
}

#' Scatter fillgradient objects
#'
#' Sets a fill gradient. If not specified, the fillcolor is used instead.
#' The object for the \code{fillgradient} of a scatter trace
#' (\code{\link{go_scatter}()}). \code{go_scatter_fillgradient()} creates
#' one, with exactly its properties; a named list with the same properties
#' works too.
#'
#' @details
#' Nested objects are named lists, or objects of the constructors their
#' arguments name. Every property is checked against the plotly.js schema
#' when the object is created or modified.
#'
#' @param arg Optional named list, or graph object of the same type, to
#'   initialise properties from. Named arguments take precedence.
#' @param colorscale Sets the fill gradient colors as a color scale. The
#'   color scale is interpreted as a gradient applied in the direction
#'   specified by "orientation", from the lowest to the highest value of
#'   the scatter plot along that axis, or from the center to the most
#'   distant point from it, if orientation is "radial". Colorscale: a
#'   vector of colors, a two-column data.frame of (value, color), or the
#'   name of a sequential, diverging or cyclical scale in
#'   \code{\link{px_colors}()} (append \code{"_r"} to reverse).
#' @param start Sets the gradient start value. It is given as the absolute
#'   position on the axis determined by the orientiation. E.g., if
#'   orientation is "horizontal", the gradient will be horizontal and start
#'   from the x-position given by start. If omitted, the gradient starts at
#'   the lowest value of the trace along the respective axis. Ignored if
#'   orientation is "radial". Number.
#' @param stop Sets the gradient end value. It is given as the absolute
#'   position on the axis determined by the orientiation. E.g., if
#'   orientation is "horizontal", the gradient will be horizontal and end
#'   at the x-position given by end. If omitted, the gradient ends at the
#'   highest value of the trace along the respective axis. Ignored if
#'   orientation is "radial". Number.
#' @param type Sets the type/orientation of the color gradient for the
#'   fill. Defaults to "none". One of \code{"radial"}, \code{"horizontal"},
#'   \code{"vertical"}, \code{"none"}.
#' @param ... Not used: properties must be named in full.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_scatter_fillgradient} object (a named list).
#'
#' @noMd
#' @export
#' @examples
#' go_figure() |>
#'   add_scatter(
#'     fillgradient = go_scatter_fillgradient()
#'   )
go_scatter_fillgradient <- function(
    arg = NULL, ..., colorscale = NULL, start = NULL, stop = NULL,
    type = NULL, skip_invalid = FALSE
) {
  plotly_object("scatter.fillgradient", arg, environment(), list(...), skip_invalid)
}

#' Scatter line objects
#'
#' The object for the \code{line} of a scatter trace
#' (\code{\link{go_scatter}()}). \code{go_scatter_line()} creates one, with
#' exactly its properties; a named list with the same properties works too.
#'
#' @details
#' Nested objects are named lists, or objects of the constructors their
#' arguments name. Every property is checked against the plotly.js schema
#' when the object is created or modified.
#'
#' @param arg Optional named list, or graph object of the same type, to
#'   initialise properties from. Named arguments take precedence.
#' @param backoff Sets the line back off from the end point of the nth line
#'   segment (in px). This option is useful e.g. to avoid overlap with
#'   arrowhead markers. With "auto" the lines would trim before markers if
#'   `marker.angleref` is set to "previous". Number in the interval [0,
#'   Inf], or a vector of these.
#' @param color Sets the line color. Color: a CSS color string or R color
#'   name.
#' @param dash Sets the dash style of lines. Set to a dash type string
#'   ("solid", "dot", "dash", "longdash", "dashdot", or "longdashdot") or a
#'   dash length list in px (eg "5px,10px,2px,2px"). One of \code{"solid"},
#'   \code{"dot"}, \code{"dash"}, \code{"longdash"}, \code{"dashdot"},
#'   \code{"longdashdot"}, or a string matching
#'   \code{"^\\\\d+(\\\\.\\\\d+)?(px|\%)?((,|\\\\s)\\\\s*\\\\d+(\\\\.\\\\d+)?(px|\%)?)*$"}.
#' @param shape Determines the line shape. With "spline" the lines are
#'   drawn using spline interpolation. The other available values
#'   correspond to step-wise line shapes. One of \code{"linear"},
#'   \code{"spline"}, \code{"hv"}, \code{"vh"}, \code{"hvh"}, \code{"vhv"}.
#' @param simplify Simplifies lines by removing nearly-collinear points.
#'   When transitioning lines, it may be desirable to disable this so that
#'   the number of points along the resulting SVG path is unaffected.
#'   Logical.
#' @param smoothing Has an effect only if `shape` is set to "spline" Sets
#'   the amount of smoothing. 0 corresponds to no smoothing (equivalent to
#'   a "linear" shape). Number in the interval [0, 1.3].
#' @param width Sets the line width (in px). Number in the interval [0,
#'   Inf].
#' @param ... Not used: properties must be named in full.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_scatter_line} object (a named list).
#'
#' @noMd
#' @export
#' @examples
#' go_figure() |>
#'   add_scatter(
#'     line = go_scatter_line(color = "red")
#'   )
go_scatter_line <- function(
    arg = NULL, ..., backoff = NULL, color = NULL, dash = NULL,
    shape = NULL, simplify = NULL, smoothing = NULL, width = NULL,
    skip_invalid = FALSE
) {
  plotly_object("scatter.line", arg, environment(), list(...), skip_invalid)
}

#' Scatter marker objects
